(()=>{const e=async e=>{(async e=>{const n=document.getElementById("content");switch(e.status){case 200:n.innerHTML="<b>Success!!</b>";break;case 400:n.innerHTML="<b>Bad Request</b>";break;case 404:n.innerHTML="<b>Not Found</b>";break;default:n.innerHTML="<p>Status Code not Implemented By Client</p>"}const t=await e.json();n.innerHTML+=`<p>${t.message}</p>`})(await fetch(e))};window.onload=()=>{const n=document.querySelector("#success"),t=document.querySelector("#badRequest"),c=document.querySelector("#notFound");n.addEventListener("click",()=>e("/success")),t.addEventListener("click",()=>e("/badRequest")),c.addEventListener("click",()=>e("/somethingUnhandled"))}})();